-- Isolated disposable local Postgres only; bootstrap and prerequisite migrations first.
\set ON_ERROR_STOP on
create or replace function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERT: %',message; end if; end $$;
begin;
insert into auth.users(id,email,email_confirmed_at)
 select ('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'dm'||n||'@stonybrook.edu',case when n=4 then null else now() end from generate_series(1,70)n;
insert into auth.identities select id,'google',jsonb_build_object('email',email,'email_verified',true) from auth.users where id::text like '50000000-%';
insert into public.user_courses(user_id,course_code) select id,'CSE 310' from auth.users where id::text like '50000000-%' and right(id::text,12)::int not in(3,4,5,6);
insert into public.friendships(user_id,friend_id) values('50000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000005');
insert into public.friend_requests(sender_id,recipient_id) values('50000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000001');
select pg_temp.assert((select bool_and(allow_new_dms) from public.profiles),'default true including existing profiles');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
select pg_temp.assert(public.dm_contact_state('50000000-0000-0000-0000-000000000003') is null,'UUID alone not contact');
select pg_temp.assert(public.dm_contact_state('50000000-0000-0000-0000-000000000001','CSE310') is null,'self denied');
select pg_temp.assert((public.dm_contact_state('50000000-0000-0000-0000-000000000002','cse310')->>'can_send')::boolean,'shared-course contact');
select pg_temp.assert((public.dm_contact_state('50000000-0000-0000-0000-000000000005')->>'can_send')::boolean,'accepted friend without course');
select pg_temp.assert((public.dm_contact_state('50000000-0000-0000-0000-000000000006')->>'can_send')::boolean,'pending request without course');
select pg_temp.assert((select count(*)=0 from public.dm_conversations),'opening contact does not create thread');
select public.dm_send_message('50000000-0000-0000-0000-000000000002',E'Hi <script>literal</script>\n😀','70000000-0000-0000-0000-000000000001','CSE310');
select set_config('test.dm_thread',(public.dm_contact_state('50000000-0000-0000-0000-000000000002')->>'conversation_id'),true);
select public.dm_send_message('50000000-0000-0000-0000-000000000002',E'Hi <script>literal</script>\n😀','70000000-0000-0000-0000-000000000001');
select pg_temp.assert((select count(*)=1 from public.dm_messages),'replay stored once');
select pg_temp.assert((select last_sequence=1 from public.dm_conversations),'replay does not increment');
do $$ begin
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000002','changed','70000000-0000-0000-0000-000000000001'); raise exception 'changed reuse'; exception when unique_violation then null; end;
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000005','other','70000000-0000-0000-0000-000000000001'); raise exception 'recipient reuse'; exception when unique_violation then null; end;
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000003','forged',gen_random_uuid()); raise exception 'unrelated'; exception when insufficient_privilege then null; end;
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000004','ineligible',gen_random_uuid()); raise exception 'ineligible'; exception when insufficient_privilege then null; end;
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000002',chr(160)||chr(65279)||E'\n\t',gen_random_uuid()); raise exception 'blank'; exception when invalid_parameter_value then null; end;
 begin perform public.dm_send_message('50000000-0000-0000-0000-000000000002',repeat('😀',2001),gen_random_uuid()); raise exception 'oversized'; exception when invalid_parameter_value then null; end;
 begin insert into public.dm_messages(conversation_id,sequence,sender_id,client_message_id,body) values(current_setting('test.dm_thread')::uuid,99,auth.uid(),gen_random_uuid(),'bypass'); raise exception 'direct insert'; exception when insufficient_privilege then null; end;
 begin update public.dm_messages set body='edit'; raise exception 'direct edit'; exception when insufficient_privilege then null; end;
 begin delete from public.dm_conversations; raise exception 'direct delete'; exception when insufficient_privilege then null; end;
end $$;
select public.dm_send_message('50000000-0000-0000-0000-000000000005','Friend',gen_random_uuid());
select public.dm_send_message('50000000-0000-0000-0000-000000000006','Request',gen_random_uuid());
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
update public.profiles set allow_new_dms=false where id=auth.uid();
select public.dm_send_message('50000000-0000-0000-0000-000000000001','Reply despite closed DMs',gen_random_uuid());
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000007',true);
update public.profiles set allow_new_dms=false where id=auth.uid();
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
select pg_temp.assert(public.dm_contact_state('50000000-0000-0000-0000-000000000007','CSE310')->>'reason'='closed','new recipient closed');
do $$ begin begin perform public.dm_send_message('50000000-0000-0000-0000-000000000007','first',gen_random_uuid(),'CSE310'); raise exception 'closure ignored'; exception when raise_exception then if sqlerrm='closure ignored' then raise; end if; end; end $$;
select pg_temp.assert((select count(*)=3 from public.dm_conversations),'failed send no empty thread');
reset role;
delete from public.user_courses where user_id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select public.dm_send_message('50000000-0000-0000-0000-000000000002','Existing thread after course loss',gen_random_uuid());
do $$ declare n integer; begin
 for n in 1..65 loop perform public.dm_send_message('50000000-0000-0000-0000-000000000002',n::text,gen_random_uuid()); end loop;
 for n in 8..70 loop perform public.dm_send_message(('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Inbox page',gen_random_uuid(),'CSE310'); end loop;
end $$;
select pg_temp.assert(jsonb_array_length(public.dm_history(current_setting('test.dm_thread')::uuid))=50,'bounded latest history');
select pg_temp.assert(jsonb_array_length(public.dm_history(current_setting('test.dm_thread')::uuid,19))=18,'older history reachable');
select pg_temp.assert((public.dm_history(current_setting('test.dm_thread')::uuid,null,0)->0->>'sequence')::int=1,'catchup ascending first');
select pg_temp.assert(jsonb_array_length(public.dm_history(current_setting('test.dm_thread')::uuid,null,50))=18,'catchup next page');
select pg_temp.assert(jsonb_array_length(public.dm_inbox())=50,'bounded inbox');
select pg_temp.assert((select jsonb_array_length(public.dm_inbox((x->>'last_message_at')::timestamptz,(x->>'conversation_id')::uuid))=16 from (select public.dm_inbox()->49 x)t),'older inbox reachable');
do $$ begin
 begin perform public.dm_history(current_setting('test.dm_thread')::uuid,99999); raise exception 'foreign cursor'; exception when invalid_parameter_value then null; end;
 begin perform public.dm_history(current_setting('test.dm_thread')::uuid,1,1); raise exception 'conflicting cursors'; exception when invalid_parameter_value then null; end;
 begin perform public.dm_inbox(null,gen_random_uuid()); raise exception 'bad inbox cursor'; exception when invalid_parameter_value then null; end;
end $$;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000003',true);
select pg_temp.assert((select count(*)=0 from public.dm_messages),'unrelated direct reads denied');
select pg_temp.assert(public.dm_inbox()='[]','unrelated inbox empty');
do $$ begin begin perform public.dm_history(current_setting('test.dm_thread')::uuid); raise exception 'history leak'; exception when insufficient_privilege then null; end; end $$;
reset role;
update auth.users set email_confirmed_at=null where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
select pg_temp.assert(public.dm_contact_state('50000000-0000-0000-0000-000000000002')->>'name'='Unavailable student','ineligible peer neutral identity');
select pg_temp.assert(jsonb_array_length(public.dm_history(current_setting('test.dm_thread')::uuid))=50,'history remains readable');
do $$ begin begin perform public.dm_send_message('50000000-0000-0000-0000-000000000002','no',gen_random_uuid()); raise exception 'ineligible send'; exception when insufficient_privilege then null; end; end $$;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000004',true);
select pg_temp.assert((select count(*)=0 from public.dm_messages),'ineligible direct reads denied');
do $$ begin begin perform public.dm_inbox(); raise exception 'ineligible inbox'; exception when insufficient_privilege then null; end; end $$;
reset role;
set local role anon;
do $$ begin begin perform public.dm_inbox(); raise exception 'anon inbox'; exception when insufficient_privilege then null; end; end $$;
rollback;
